import { CONDITIONS, DEFAULT_REFILL_DAYS, OTHER, SEX } from '../config.js';
import { createPatient, listCatalog } from '../supabase.js';
import { createMedicationPicker } from '../components/medication-picker.js';
import { altLabels } from '../lib/catalog.js';
import { today } from '../lib/dates.js';
import { notify, opts, showLoadError, toggle, withBusy } from '../lib/dom.js';

// Add patient. The Medication section is optional (hidden until "Dispense medication" is clicked).
export async function render(view, { go }) {
  let catalog;
    try {
        catalog = await listCatalog();
          } catch (err) {
              showLoadError(view, err);
                  return;
                    }

                      let showMed = false;
                        let rows = []; // pickers currently on screen: [{ wrap, picker }]

                          view.innerHTML = `<div class="form"><h2 class="title" style="margin-bottom:20px">Add patient</h2>
                              <form id="af">
                                    <div class="box sec"><h3>Patient details</h3>
                                            <div class="two"><div><label>Full name</label><input name="name" required placeholder="e.g. John Banda"></div></div>
                                                    <div class="two" style="margin:0">
                                                              <div><label>Phone number</label><input name="phone" type="tel" placeholder="e.g. +260 97 000 0000"></div>
                                                                        <div><label>Condition</label><select name="cond">${opts([...CONDITIONS, OTHER], CONDITIONS[0])}</select>
                                                                                    <input name="custom" class="hide" placeholder="Specify condition" style="margin-top:8px"></div>
                                                                                            </div>
                                                                                                    <div class="two" style="margin:14px 0 0">
                                                                                                              <div><label>Date of birth</label><input name="dob" type="date" required max="${today()}"></div>
                                                                                                                        <div><label>Sex</label><select name="sex" required><option value="">Select</option>${opts(SEX, '')}</select></div>
                                                                                                                                </div>
                                                                                                                                        <div style="margin-top:14px"><label>Address</label><input name="addr" required placeholder="e.g. House number, street, area, town"></div>
                                                                                                                                              </div>

                                                                                                                                                    <div class="box sec" id="medoff"><h3>Medication <span class="sub" style="font-weight:400">(optional)</span></h3>
                                                                                                                                                            <p class="sub" style="margin:0 0 12px">Leave this out to register the patient now and dispense later.</p>
                                                                                                                                                                    <button type="button" class="btn sm" id="showmed">Dispense medication</button></div>

                                                                                                                                                                          <div class="box sec hide" id="medon">
                                                                                                                                                                                  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><h3 style="margin:0">Medication</h3>
                                                                                                                                                                                            <button type="button" class="btn sm" id="hidemed">Remove</button></div>
                                                                                                                                                                                                    <div id="pickers"></div>
                                                                                                                                                                                                            <button type="button" class="btn sm" id="addmore" style="margin-bottom:14px">+ Add another medication</button>
                                                                                                                                                                                                                    <div class="two">
                                                                                                                                                                                                                              <div><label>Refill every (days)</label><input name="every" type="number" min="1" value="${DEFAULT_REFILL_DAYS}"></div>
                                                                                                                                                                                                                                        <div><label>Date last given</label><input name="last" type="date" value="${today()}"></div>
                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                        <label class="chk"><input type="checkbox" name="isAlt">Alternative medication given instead</label>
                                                                                                                                                                                                                                                                <div id="altbox" class="hide two" style="margin:14px 0 0">
                                                                                                                                                                                                                                                                          <div><label>Alternative given</label><select name="altsel"></select>
                                                                                                                                                                                                                                                                                      <input name="altother" class="hide" placeholder="Specify alternative" style="margin-top:8px"></div>
                                                                                                                                                                                                                                                                                                <div><label>Reason</label><input name="reason" placeholder="e.g. Out of stock"></div>
                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                    <div class="acts"><a class="btn" href="#/dashboard">Cancel</a><button class="btn p">Save patient</button></div>
                                                                                                                                                                                                                                                                                                                        </form></div>`;

                                                                                                                                                                                                                                                                                                                          const form = view.querySelector('#af');
                                                                                                                                                                                                                                                                                                                            const q = (sel) => view.querySelector(sel);
                                                                                                                                                                                                                                                                                                                              const condition = () => (form.elements.cond.value === OTHER ? form.elements.custom.value.trim() : form.elements.cond.value);
                                                                                                                                                                                                                                                                                                                                // The catalog is keyed by the chosen standard condition; custom conditions have no list.
                                                                                                                                                                                                                                                                                                                                  const catalogKey = () => (form.elements.cond.value === OTHER ? '' : form.elements.cond.value);

                                                                                                                                                                                                                                                                                                                                    function addPicker() {
                                                                                                                                                                                                                                                                                                                                        const wrap = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                            const index = rows.length;
                                                                                                                                                                                                                                                                                                                                                wrap.className = index ? 'sb' : '';
                                                                                                                                                                                                                                                                                                                                                    if (index) {
                                                                                                                                                                                                                                                                                                                                                          wrap.innerHTML = `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
                                                                                                                                                                                                                                                                                                                                                                  <b style="font-size:13px">Additional medication</b><button type="button" class="btn sm" data-remove>Remove</button></div>`;
                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                          const picker = createMedicationPicker(catalog, catalogKey());
                                                                                                                                                                                                                                                                                                                                                                              wrap.appendChild(picker.el);
                                                                                                                                                                                                                                                                                                                                                                                  q('#pickers').appendChild(wrap);
                                                                                                                                                                                                                                                                                                                                                                                      rows.push({ wrap, picker });
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                          function resetPickers() {
                                                                                                                                                                                                                                                                                                                                                                                              q('#pickers').innerHTML = '';
                                                                                                                                                                                                                                                                                                                                                                                                  rows = [];
                                                                                                                                                                                                                                                                                                                                                                                                      addPicker();
                                                                                                                                                                                                                                                                                                                                                                                                          form.elements.altsel.innerHTML = `<option value="">Select</option>${opts([...altLabels(catalog, catalogKey()), OTHER], '')}`;
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                              q('#showmed').addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                  showMed = true;
                                                                                                                                                                                                                                                                                                                                                                                                                      toggle(q('#medoff'), false);
                                                                                                                                                                                                                                                                                                                                                                                                                          toggle(q('#medon'), true);
                                                                                                                                                                                                                                                                                                                                                                                                                              resetPickers();
                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                  q('#hidemed').addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                      showMed = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                          toggle(q('#medon'), false);
                                                                                                                                                                                                                                                                                                                                                                                                                                              toggle(q('#medoff'), true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  q('#pickers').innerHTML = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                      rows = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                          form.elements.isAlt.checked = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                              toggle(q('#altbox'), false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  q('#addmore').addEventListener('click', addPicker);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    q('#pickers').addEventListener('click', (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!e.target.closest('[data-remove]')) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const wrap = e.target.closest('.sb');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                rows = rows.filter((r) => r.wrap !== wrap);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    wrap.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        form.addEventListener('change', (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const t = e.target;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (t.name === 'cond') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      toggle(form.elements.custom, t.value === OTHER);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            form.elements.custom.required = t.value === OTHER;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (showMed) resetPickers(); // medication lists depend on the condition
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else if (t.name === 'isAlt') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            toggle(q('#altbox'), t.checked);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  form.elements.altsel.required = t.checked;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        form.elements.reason.required = t.checked;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (t.name === 'altsel') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  toggle(form.elements.altother, t.value === OTHER);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        form.elements.altother.required = t.value === OTHER;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                form.addEventListener('submit', async (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const f = form.elements;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const alt = showMed && f.isAlt.checked ? (f.altsel.value === OTHER ? f.altother.value : f.altsel.value).trim() : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const fields = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      name: f.name.value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            phone: f.phone.value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  dob: f.dob.value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sex: f.sex.value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              address: f.addr.value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    condition: condition(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          refill_every: showMed ? Number(f.every.value) || DEFAULT_REFILL_DAYS : DEFAULT_REFILL_DAYS,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                last_given: showMed ? f.last.value || today() : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      alt_medication: alt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alt_reason: alt ? f.reason.value.trim() : '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const medications = showMed ? rows.map((r) => r.picker.read()) : [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const saved = await withBusy(e.submitter, async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await createPatient(fields, medications);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (saved) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  notify('Patient saved');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        go('#/dashboard');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              